class MemLayout {
    int A; // Declared first: Lowest memory address
    int B; // Declared second: Higher memory address
public:
    // Initialization order (A then B) follows declaration order,
    // REGARDLESS of initializer list order (B then A).

    // A is initialized first (A=10).
    // B is initialized second (B=10+1=11).
    MemLayout() : B(A + 1), A(10) {}
};
// Memory Layout determined by declaration order: [A] [B]
// Warning: Initializing B using A when A is uninitialized/defaulted
// (if A was initialized later in the list) is UB in complex cases.
